structure.recommended_css:
/* In <head>: <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"> */

*, *::before, *::after { box-sizing: border-box; }

/* The route shell: exactly the visible viewport, never taller. */
.detail-screen {
  height: 100vh;   /* fallback for engines without dvh */
  height: 100dvh;  /* preferred; overrides the fallback where supported */
  display: flex;
  flex-direction: column;
  overflow: hidden;                 /* the shell itself never scrolls */
  overscroll-behavior: none;        /* no page bounce / pull-to-refresh behind it */
  background: var(--paper);
}

/* Fixed header: in flow, never position:fixed. */
.detail-header {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 12px;
  /* Safe-area: top, and side notches in landscape. */
  padding-top: max(12px, env(safe-area-inset-top));
  padding-left: max(16px, env(safe-area-inset-left));
  padding-right: max(16px, env(safe-area-inset-right));
  padding-bottom: 12px;
  border-bottom: 1px solid var(--hairline);
}

/* Scrolling body: the only scroller. min-height:0 lets it shrink below content size. */
.detail-body {
  flex: 1 1 auto;
  min-height: 0;                    /* the critical flex primitive */
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;     /* stop scroll chaining to the page */
  padding: 16px;
  padding-left: max(16px, env(safe-area-inset-left));
  padding-right: max(16px, env(safe-area-inset-right));
}

/* Pinned footer: in flow, pinned by flex, never overlapping the scroller. */
.detail-footer {
  flex: 0 0 auto;
  display: flex;
  gap: 12px;
  padding: 12px 16px;
  padding-bottom: calc(12px + env(safe-area-inset-bottom, 0px));
  border-top: 1px solid var(--hairline);
}

/* If the detail view is a MODAL (<dialog>) instead of a route: */
dialog.detail-sheet {
  width: 100%;
  max-width: 100%;
  height: 100dvh;
  max-height: 100dvh;
  margin: 0;
  border: 0;
  padding: 0;
  overscroll-behavior: contain;
  overflow: hidden;                 /* makes it a scroll container (needed for older engines) */
}
dialog.detail-sheet::backdrop { background: rgba(0,0,0,.4); }
/* Lock page scroll behind the dialog without JS (modern): */
body:has(dialog.detail-sheet[open]) { overflow: hidden; }

:root {
  --paper: #fff;
  --hairline: rgba(0,0,0,.12);
}
